def lru_sim(cap, keys):
    cache = {}
    lru = []
    hits = 0
    for key in keys:
        if key in cache:
            hits += 1
            lru.remove(key)
        else:
            if len(cache) == cap:
                lru_key = lru.pop(0)
                del cache[lru_key]
            cache[key] = None
        lru.append(key)
    return hits
